INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 3, '{"stem": "应用(7)：买4个水壶和8个水桶要付192元，买4个水壶和2个水桶要付120元，一个水壶和一个水桶各多少元？（6分）"}', '水壶24元，水桶12元', '192-120=72元(6个水桶); 72÷6=12元(水桶); 120-12×2=96元(4水壶); 96÷4=24元(水壶)', 'jsj3_sx_v114', '["jsj3_sx","qizhong2","p087","apply_07"]', 1, NULL);